function biomeForDepth(d=G.depth){return BIOMES[(d-1)%BIOMES.length];}
function biomeAtCell(x,z){const r=rooms&&rooms.find(r=>x>=r.x&&x<r.x+r.w&&z>=r.y&&z<r.y+r.h);return r&&r.biome||biomeForDepth();}
function roomAt(pos){return rooms.find(r=>pos.x/TILE>=r.x&&pos.x/TILE<r.x+r.w&&pos.z/TILE>=r.y&&pos.z/TILE<r.y+r.h);}
function escaped(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function sound(kind){if(!audioCtx||SETTINGS.volume<=0)return;const now=audioCtx.currentTime;const o=audioCtx.createOscillator(),g=audioCtx.createGain();const tones={swing:[180,60,.13,'triangle'],hit:[110,42,.16,'sawtooth'],loot:[640,960,.16,'sine'],dodge:[220,95,.16,'sine'],magic:[300,1100,.25,'sine'],parry:[960,430,.3,'triangle'],chest:[180,560,.4,'triangle'],step:[85,45,.045,'triangle'],death:[150,28,.6,'sawtooth'],level:[420,840,.55,'sine']};const t=tones[kind]||tones.hit;o.type=t[3];o.frequency.setValueAtTime(t[0],now);o.frequency.exponentialRampToValueAtTime(t[1],now+t[2]);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(kind==='step'?.025:.11,now+.01);g.gain.exponentialRampToValueAtTime(.0001,now+t[2]);o.connect(g);g.connect(audioGain);o.start();o.stop(now+t[2]+.03);o.onended=()=>{o.disconnect();g.disconnect();};}
function initAudio(){try{if(!audioCtx){audioCtx=new(window.AudioContext||window.webkitAudioContext)();audioGain=audioCtx.createGain();audioGain.connect(audioCtx.destination);}audioGain.gain.value=SETTINGS.volume;audioCtx.resume().catch(()=>{});}catch{}}
