function pathWaypoint(e,goal){e.navTimer=(e.navTimer||0)-.016;if(e.path&&e.path.length&&e.navTimer>0){while(e.path.length>1&&Math.hypot(e.pos.x-e.path[0].x,e.pos.z-e.path[0].z)<1)e.path.shift();return e.path[0];}e.navTimer=.8;const [sx,sz]=cellOf(e.pos.x,e.pos.z),[tx,tz]=cellOf(goal.x,goal.z),start=sz*CW+sx,target=tz*CW+tx;if(!walkCell(tx,tz))return null;const q=[start],prev=new Int32Array(CW*CH).fill(-1);prev[start]=start;for(let i=0;i<q.length;i++){const n=q[i];if(n===target)break;const x=n%CW,z=Math.floor(n/CW);for(const [dx,dz]of[[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,nz=z+dz,nn=nz*CW+nx;if(walkCell(nx,nz)&&prev[nn]===-1){prev[nn]=n;q.push(nn);}}}if(prev[target]===-1)return null;const route=[];let n=target;while(n!==start){route.push(new BABYLON.Vector3((n%CW+.5)*TILE,GROUND,(Math.floor(n/CW)+.5)*TILE));n=prev[n];}e.path=route.reverse();return e.path[0]||null;}
losClear=function(a,b){const dx=b.x-a.x,dz=b.z-a.z,len2=dx*dx+dz*dz,n=Math.max(1,Math.ceil(Math.sqrt(len2)/.45));for(let i=1;i<n;i++)if(!walkableAt(a.x+dx*i/n,a.z+dz*i/n))return false;if(len2<.001)return true;for(const q of world.blockers){if(q.crate&&q.crate.open||q.height!==undefined&&q.height<.8)continue;const t=((q.x-a.x)*dx+(q.z-a.z)*dz)/len2;if(t<=.03||t>=.97)continue;const x=a.x+dx*t-q.x,z=a.z+dz*t-q.z;if(x*x+z*z<q.r*q.r*.72)return false;}return true;};
let entityBuckets=new Map(),blockBuckets=new Map();
function bucketKey(x,z){return Math.floor(x/5)+','+Math.floor(z/5);}
function nearby(map,x,z){const out=[],cx=Math.floor(x/5),cz=Math.floor(z/5);for(let dx=-1;dx<=1;dx++)for(let dz=-1;dz<=1;dz++){const a=map.get((cx+dx)+','+(cz+dz));if(a)out.push(...a);}return out;}
function rebuildBuckets(){entityBuckets.clear();for(const e of[player,...G.enemies]){if(e.dead||e.removed)continue;const k=bucketKey(e.pos.x,e.pos.z);if(!entityBuckets.has(k))entityBuckets.set(k,[]);entityBuckets.get(k).push(e);}}
