stepMove=function(e,dx,dz){const steps=Math.max(1,Math.ceil(Math.hypot(dx,dz)/.18));for(let i=0;i<steps;i++){const x=e.pos.x+dx/steps,z=e.pos.z+dz/steps;if(clearPoint(x,e.pos.z,e.radius))e.pos.x=x;if(clearPoint(e.pos.x,z,e.radius))e.pos.z=z;}};
separation=function(e){const v=new BABYLON.Vector3(0,0,0);for(const q of nearby(entityBuckets,e.pos.x,e.pos.z)){if(q===e||q.dead)continue;const dx=e.pos.x-q.pos.x,dz=e.pos.z-q.pos.z,d=Math.hypot(dx,dz),r=e.radius+q.radius+.4;if(d>.001&&d<r){v.x+=dx/d*(r-d);v.z+=dz/d*(r-d);}}return v;};
resolveCollisions=function(){for(let pass=0;pass<2;pass++){rebuildBuckets();for(const e of[player,...G.enemies]){if(e.dead)continue;for(const b of nearby(blockBuckets,e.pos.x,e.pos.z)){if(b.crate&&b.crate.open)continue;let dx=e.pos.x-b.x,dz=e.pos.z-b.z;let d=Math.hypot(dx,dz),r=e.radius+b.r;if(d<r){if(d<.001){dx=1;dz=0;d=1;}stepMove(e,dx/d*(r-d+.005),dz/d*(r-d+.005));}}for(const q of nearby(entityBuckets,e.pos.x,e.pos.z)){if(q===e||q.dead||Math.abs(q.pos.y-e.pos.y)>(q.rig.height+e.rig.height)*.5||q.passive&&e.isPlayer||e.passive&&q.isPlayer)continue;let dx=e.pos.x-q.pos.x,dz=e.pos.z-q.pos.z,d=Math.hypot(dx,dz),r=e.radius+q.radius;if(d>.001&&d<r){const push=(r-d)*.3;stepMove(e,dx/d*push,dz/d*push);}}}}};
