updateEnemy=function(e,dt){if(e.passive){updatePassive(e,dt);return;}if(!e.dead&&e.stunned>0){e.stunned-=dt;e.moveSpeedNow=0;updateRig(e,dt);return;}if(e.status&&!e.dead){if(e.status.burn>0){e.status.burn-=dt;e.burnTick=(e.burnTick||0)+dt;if(e.burnTick>.5){e.burnTick=0;hitEnemy(e,e.maxhp*.006+player.stats.baseDmg*.08,false,player.pos);}}e.status.chill=Math.max(0,e.status.chill-dt);}const sp=e.speed,wasEnraged=!!e.enraged;if(e.status&&e.status.chill>0)e.speed*=.55;base.updateEnemy(e,dt);e.speed=sp*(!wasEnraged&&e.enraged?1.3:1);if(e.rig.anim.atkT>=0&&e.rig.anim.phase===0&&e.spec.atk.style==='slam')showTelegraph(e);};
