updateFX=function(dt){for(let i=G.fx.length-1;i>=0;i--){const f=G.fx[i];f.life-=dt;if(f.ring){const t=1-f.life/f.max;f.mesh.scaling.set(t*f.radius*2,1,t*f.radius*2);f.mat.alpha=.55*(1-t);}else{f.vel.y-=(f.grav||0)*9.8*dt;f.mesh.position.addInPlace(f.vel.scale(dt));f.mesh.rotation.x+=dt*4;f.mesh.rotation.z+=dt*5;}if(f.life<=0){killNode(f.mesh);if(f.mat)f.mat.dispose();G.fx.splice(i,1);}}
 for(let i=G.projectiles.length-1;i>=0;i--)stepProjectile(G.projectiles[i],dt);
 for(let i=EXT.telegraphs.length-1;i>=0;i--){const t=EXT.telegraphs[i];if(t.e.dead||t.e.rig.anim.atkT<0||t.e.rig.anim.phase!==0){t.mesh.dispose();t.e.telegraph=null;EXT.telegraphs.splice(i,1);}else{const k=1+Math.sin(G.time*15)*.04;t.mesh.scaling.set(k,1,k);}}
};
hitEnemy=function(e,dmg,crit,from){if(e.passive)return;base.hitEnemy(e,dmg,crit,from);sound('hit');G.cameraKick=crit?.035:.015;RUN.journal.add(e.key);};
hitPlayer=function(dmg,from,kind){if(player.dead||player.invuln>0)return;if(kind!=='environment'&&player.blocking&&G.time-(player.guardAt||-10)<.22&&player.guardBreak<=0){const fw=new BABYLON.Vector3(-Math.sin(player.yaw),0,-Math.cos(player.yaw));const to=(from||player.pos.add(fw)).subtract(player.pos);to.y=0;to.normalize();if(BABYLON.Vector3.Dot(fw,to)>.45&&player.stam>=8){player.stam-=8;player.invuln=.2;meterAdd('blocked',dmg);spark(player.pos,'#b6f8df',15);popDamage(player.pos.add(new BABYLON.Vector3(0,2,0)),'PERFECT GUARD','#b6f8df',true);sound('parry');for(const e of nearby(entityBuckets,player.pos.x,player.pos.z))if(!e.isPlayer&&!e.passive&&!e.dead&&BABYLON.Vector3.Distance(e.pos,player.pos)<4){e.stunned=1.0;e.rig.anim.atkT=-1;}return;}}base.hitPlayer(dmg,from,kind);G.cameraKick=.055;};
killEnemy=function(e){if(e.dead)return;base.killEnemy(e);G.deadIds.add(e.eid);RUN.floorKills++;const gold=Math.round((e.boss?160:e.elite?35:6+e.xp*.12)*(1+G.depth*.12));player.gold+=gold;RUN.shards+=e.boss?5:e.elite?2:rnd()<.12?1:0;spark(e.pos,e.spec.glow||'#d6c49d',e.boss?24:10);if(e.boss){RUN.crowns=(RUN.crowns||0)+1;toast('Crown fragment recovered · +'+gold+' gold · +5 shards','#dcc489');if(G.mode==='dungeon'&&G.depth===4){const victoryScene=scene;setTimeout(()=>{if(scene===victoryScene&&G.running&&!player.dead)showVictory();},2000);}}};
function castPulse(){if(!canAct()||RUN.abilities.pulse>0||player.stam<30)return;RUN.abilities.pulse=9;player.stam-=30;player.calm=0;player.rig.anim.atkT=-1;shockwave(player.pos,6,'#83dcca');spark(player.pos,'#b8f7e7',18);sound('magic');for(const e of G.enemies)if(!e.dead&&!e.passive&&BABYLON.Vector3.Distance(e.pos,player.pos)<6&&losClear(player.pos,e.pos)){hitEnemy(e,player.stats.baseDmg*1.6,false,player.pos);e.stunned=e.boss?.25:1.1;}toast('Runic pulse','#83dcca');}
computeStats=function(p){const oldHp=p.hp,s=base.computeStats(p);p.maxhp+=RUN.perks.vigor*18;p.hp=Math.min(oldHp,p.maxhp);s.baseDmg*=1+RUN.perks.force*.06;p.speed*=1+RUN.perks.haste*.04;return s;};
updatePlayer=function(dt){RUN.abilities.pulse=Math.max(0,RUN.abilities.pulse-dt);const was=player.blocking;const extraX=PAD.x+TOUCH.x,extraY=PAD.y+TOUCH.y;const old={w:keys.w,a:keys.a,s:keys.s,d:keys.d};if(Math.abs(extraX)>.15){keys.d=extraX>0;keys.a=extraX<0;}if(Math.abs(extraY)>.15){keys.w=extraY<0;keys.s=extraY>0;}const sp=player.speed;if(keys.shift&&!mouse.right&&player.stam>5&&(keys.w||keys.a||keys.s||keys.d)){player.speed*=1.42;player.stam=Math.max(0,player.stam-dt*15);}base.updatePlayer(dt);player.speed=sp;Object.assign(keys,old);if(player.blocking&&!was)player.guardAt=G.time;if(player.moveSpeedNow>1){player.stepClock=(player.stepClock||0)+dt;if(player.stepClock>.38){player.stepClock=0;sound('step');}}};
/* Loot is only removed after successful collection. */
pickupItem=function(it){if(!it)return false;player.bag.push(it);toast(it.name,RARITY[it.rarity].c);if(it.rarity>=3)logMsg('Recovered '+it.name);if(isUpgrade(it))flashBetter();if(G.invOpen)refreshInv();sound('loot');return true;};
updateDrops=function(dt){for(let i=G.drops.length-1;i>=0;i--){const d=G.drops[i];d.t+=dt;d.mesh.position.y=groundAt(d.pos.x,d.pos.z)+.55+Math.sin(d.t*2.2)*.09;d.mesh.rotation.y+=dt*.6;d.hm.alpha=.3+Math.sin(d.t*3)*.1;const dist=Math.hypot(d.pos.x-player.pos.x,d.pos.z-player.pos.z);if(dist<1.5&&!player.dead&&(SETTINGS.autoLoot||G.pickupNow)){if(d.isPotion){player.potions++;toast('Health elixir · '+player.potions,'#eaa392');sound('loot');}else if(!pickupItem(d.item)){if(!d.warned){d.warned=true;toast('Satchel full. Loot remains here.','#d9b574');}continue;}killNode(d.mesh);d.halo.dispose();d.hm.dispose();G.drops.splice(i,1);}}G.pickupNow=false;};
function nearStation(which){const p=which==='forge'?RUN.forgePos:RUN.shrinePos;return p&&Math.hypot(player.pos.x-p.x,player.pos.z-p.z)<3.4;}
updateCrates=function(dt){let prompt='';for(const c of G.crates){if(c.open){c.t=Math.min(1.4,c.t+dt);if(c.lid)c.lid.rotation.x=easeOutCubic(c.t/1.4)*1.85;}else if(BABYLON.Vector3.Distance(c.pos,player.pos)<2.6)prompt='Open '+(c.rarity>=3?'sealed reliquary':'treasure chest');}if(nearStation('forge'))prompt='Use the wayfarer’s forge';if(nearStation('shrine'))prompt='Commune with the shrine';if(G.shaft&&Math.hypot(G.shaft.position.x-player.pos.x,G.shaft.position.z-player.pos.z)<3)prompt='Descend to depth '+(G.depth+1);if(!SETTINGS.autoLoot&&G.drops.some(d=>Math.hypot(d.pos.x-player.pos.x,d.pos.z-player.pos.z)<1.5))prompt='Collect nearby loot';$('prompt').style.display=prompt?'block':'none';$('prompt').innerHTML='<b>'+(document.body.classList.contains('touch')?'USE':PAD.active?'Y':'E')+'</b> &nbsp; '+prompt;};
interact=function(){if(!canAct())return;G.pickupNow=true;if(G.shaft&&Math.hypot(G.shaft.position.x-player.pos.x,G.shaft.position.z-player.pos.z)<3){descend();return;}if(nearStation('forge')){showForge();return;}if(nearStation('shrine')){showShrine();return;}let best=null,bd=2.6;for(const c of G.crates){if(c.open)continue;const d=BABYLON.Vector3.Distance(c.pos,player.pos);if(d<bd){bd=d;best=c;}}if(!best)return;best.open=true;best.t=0;RUN.opened++;player.gold+=ri(12,24)+G.depth*3;const count=ri(2,3)+(best.rarity>=3?1:0);for(let i=0;i<count;i++){const pos=best.pos.add(new BABYLON.Vector3(rr(-.9,.9),0,rr(-.9,.9)));const rarity=i===0&&best.rarity>=3?Math.max(2,rollRarity(16)):rollRarity(8+G.depth*2);spawnDrop(makeItem(pick(SLOTS),G.depth*2+ri(0,4),rarity),clearPoint(pos.x,pos.z,.3)?pos:best.pos);}if(rnd()<.8)spawnDrop(null,best.pos,true);spark(best.pos,RARITY[best.rarity].c,16);sound('chest');logMsg('The reliquary opens.');};
dropLoot=function(e){const n=e.boss?5:e.elite?ri(2,3):rnd()<.65?1:0;for(let i=0;i<n;i++){const p=e.pos.add(new BABYLON.Vector3(rr(-.8,.8),0,rr(-.8,.8)));const rarity=e.boss&&i===0?4:e.elite&&i===0?Math.max(2,rollRarity(16)):rollRarity((e.boss?22:e.elite?14:0)+Math.min(12,G.depth));spawnDrop(makeItem(pick(SLOTS),G.depth*2+ri(0,3),rarity),clearPoint(p.x,p.z,.3)?p:e.pos);}if(rnd()<(player.potions<3?.6:.22)||e.boss)spawnDrop(null,e.pos,true);};
function updateObjectives(){const need=Math.min(4,rooms.length-1),explored=Math.min(need,RUN.discovered.size);const rows=[['Explore '+need+' chambers',explored,need],['Open 3 treasure chests',Math.min(3,RUN.opened),3],['Defeat the crowned guardian',G.bossDown?1:0,1]];$('questRows').innerHTML=rows.map(([t,n,d])=>'<div class="'+(n>=d?'done':'')+'">'+(n>=d?'✓':'·')+' '+t+' <span class="num">'+n+'/'+d+'</span></div>').join('');$('goldHud').textContent='◈ '+player.gold+' gold  ·  '+RUN.shards+' shards';if(explored>=need&&RUN.opened>=3&&G.bossDown&&!RUN.questPaid){RUN.questPaid=true;player.gold+=120+G.depth*20;RUN.shards+=3;toast('Expedition complete · gold and 3 shards awarded','#e7ce8f');sound('level');}}
function updateExploration(){const r=roomAt(player.pos);if(r&&r.id!==RUN.currentRoom){RUN.currentRoom=r.id;if(!RUN.discovered.has(r.id)){RUN.discovered.add(r.id);$('areaBanner').innerHTML='<h2>'+escaped(r.title)+'</h2><p>'+escaped(r.biome.short.toUpperCase())+'</p>';$('areaBanner').classList.add('show');G.bannerUntil=G.time+3.8;}}if(G.bannerUntil<G.time)$('areaBanner').classList.remove('show');for(const e of G.enemies)if(!e.dead&&BABYLON.Vector3.Distance(e.pos,player.pos)<12&&losClear(player.pos,e.pos))RUN.journal.add(e.key);}
updateHUD=function(){base.updateHUD();$('zoneLabel').textContent=biomeForDepth().short+' · '+String(G.depth).padStart(2,'0');$('pulseCd').textContent=RUN.abilities.pulse>0?Math.ceil(RUN.abilities.pulse)+'s':'F';$('spellSlot').style.opacity=RUN.abilities.pulse>0?'.55':'1';let target=null,score=.88;const f=new BABYLON.Vector3(Math.sin(mouse.yaw),0,Math.cos(mouse.yaw));for(const e of G.enemies){if(e.dead||e.passive||e.boss)continue;const d=e.pos.subtract(player.pos);d.y=0;const dist=d.length();const dot=BABYLON.Vector3.Dot(d.normalize(),f);if(dot>score&&dist<14&&losClear(player.pos,e.pos)){score=dot;target=e;}}const el=$('targetInfo');el.style.display=target?'block':'none';if(target){$('targetName').textContent=target.name;$('targetFill').style.width=Math.max(0,target.hp/target.maxhp*100)+'%';}};
/* Compatible JSON save records contain no engine objects or executable data. */
function itemRecord(it){if(!it)return null;return{id:it.id,slot:it.slot,ilvl:it.ilvl,rarity:it.rarity,tier:it.tier,stats:it.stats,kind:it.kind,baseDmg:it.baseDmg,reach:it.reach,hands:it.hands,base:it.base,name:it.name,colors:it.colors,score:it.score,upgrades:it.upgrades||0,affixes:it.affixes.map(x=>({k:x.a.k,v:x.v}))};}
function reviveItem(d){if(!d||!SLOTS.includes(d.slot)||!Number.isFinite(d.ilvl)||d.ilvl<1||d.ilvl>100000)return null;const def=d.slot==='weapon'?WEAPONS[d.kind]:ARMORS[d.slot];if(!def)return null;const it={...d,def,affixes:(d.affixes||[]).map(x=>({a:AFFIXES.find(a=>a.k===x.k),v:x.v})).filter(x=>x.a)};ITEM_ID=Math.max(ITEM_ID,(it.id||0)+1);return it;}
function playerCarry(){return{level:player.level,xp:player.xp,xpNext:player.xpNext,potions:player.potions,gold:player.gold,gear:Object.fromEntries(SLOTS.map(s=>[s,player.gear[s]])),bag:player.bag.slice(),hp:player.hp,kills:G.kills};}
function makeSave(){return{version:2,at:Date.now(),seed:G.levelSeed,depth:G.depth,time:G.time,nextEid:G.nextEid,kills:G.kills,bossDown:G.bossDown,deadIds:[...G.deadIds],player:{...playerCarry(),gear:Object.fromEntries(SLOTS.map(s=>[s,itemRecord(player.gear[s])])),bag:player.bag.map(itemRecord),pos:player.pos.asArray(),stam:player.stam,potCd:player.potCd},run:{class:RUN.class,shards:RUN.shards,perks:RUN.perks,crowns:RUN.crowns||0,journal:[...RUN.journal],discovered:[...RUN.discovered],opened:RUN.opened,floorKills:RUN.floorKills,questPaid:RUN.questPaid,elapsed:RUN.elapsed,abilities:RUN.abilities},enemies:G.enemies.filter(e=>!e.dead).map(e=>({key:e.key,eid:e.eid,pos:e.pos.asArray(),hp:e.hp,maxhp:e.maxhp,elite:e.elite,yaw:e.yaw,enraged:e.enraged||0})),crates:G.crates.map(c=>({cid:c.cid,pos:c.pos.asArray(),open:c.open,rarity:c.rarity})),drops:G.drops.map(d=>({item:itemRecord(d.item),pos:d.pos.asArray(),isPotion:d.isPotion}))};}
function validSave(d){const finite=(n,min=0,max=1e12)=>Number.isFinite(n)&&n>=min&&n<=max;const pos=p=>Array.isArray(p)&&p.length===3&&p.every(n=>finite(n,-1e9,1e9));const item=i=>i===null||i&&SLOTS.includes(i.slot)&&finite(i.id,1)&&finite(i.ilvl,1,100000)&&Number.isInteger(i.rarity)&&i.rarity>=0&&i.rarity<=5&&typeof i.name==='string'&&!/[<>]/.test(i.name)&&i.name.length<180&&i.stats&&Object.values(i.stats).every(n=>finite(n,0,1e9))&&i.colors&&['metal','trim','accent'].every(k=>/^#[0-9a-f]{6}$/i.test(i.colors[k]))&&finite(i.score)&&Array.isArray(i.affixes)&&i.affixes.every(a=>AFFIXES.some(q=>q.k===a.k)&&finite(a.v))&&(i.slot!=='weapon'||WEAPONS[i.kind]&&finite(i.baseDmg,1));
 try{return !!(d&&d.version===2&&Number.isInteger(d.depth)&&finite(d.depth,1)&&finite(d.seed,-2147483648,2147483647)&&d.player&&pos(d.player.pos)&&finite(d.player.level,1,10000)&&finite(d.player.hp,1)&&finite(d.player.xp)&&finite(d.player.xpNext,1)&&finite(d.player.gold)&&finite(d.player.potions)&&Array.isArray(d.player.bag)&&d.player.bag.every(item)&&d.player.gear&&SLOTS.every(k=>item(d.player.gear[k]))&&Array.isArray(d.enemies)&&d.enemies.every(e=>BESTIARY[e.key]&&pos(e.pos)&&finite(e.hp,1)&&Number.isInteger(e.eid))&&Array.isArray(d.crates)&&d.crates.length<=200&&d.crates.every(c=>pos(c.pos)&&Number.isInteger(c.cid))&&Array.isArray(d.drops)&&d.drops.every(q=>pos(q.pos)&&(q.isPotion||item(q.item)))&&d.run&&['wayfarer','knight','ranger','arcanist'].includes(d.run.class)&&Array.isArray(d.run.journal)&&Array.isArray(d.run.discovered)&&finite(d.run.shards)&&finite(d.run.elapsed)&&finite(d.run.opened)&&d.run.perks&&['vigor','force','haste'].every(k=>Number.isInteger(d.run.perks[k])&&finite(d.run.perks[k],0,8))&&d.run.abilities&&finite(d.run.abilities.pulse,0,9));}catch{return false;}}
function readSave(){try{const d=JSON.parse(localStorage.getItem('deepvault.save.v2'));return validSave(d)?d:null;}catch{return null;}}
function saveGame(quiet=false){if(!G.saveEligible||!player||player.dead||loadingLevel)return false;try{localStorage.setItem('deepvault.save.v2',JSON.stringify(makeSave()));if(!quiet)toast('Expedition saved','#9edbbb');return true;}catch{if(!G.saveFailureNotice||Date.now()-G.saveFailureNotice>30000){G.saveFailureNotice=Date.now();toast('Storage is full or unavailable. Use Pause → Export save to keep your expedition.','#e2b68c');}return false;}}
function exportSave(){if(!player||player.dead)return;const blob=new Blob([JSON.stringify(makeSave(),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='deepvault-expedition.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function restoreSave(d){if(!validSave(d))throw new Error('This is not a supported Deepvault save.');Object.assign(RUN,d.run);RUN.journal=new Set(d.run.journal||[]);RUN.discovered=new Set(d.run.discovered||[]);RUN.perks={vigor:0,force:0,haste:0,...d.run.perks};const carry={...d.player,gear:Object.fromEntries(SLOTS.map(s=>[s,reviveItem(d.player.gear[s])])),bag:d.player.bag.map(reviveItem).filter(Boolean),kills:d.kills};closeModal(false);await loadLevel(d.depth,carry,d.seed,d);}
function restoreWorld(d){player.pos.copyFromFloats(...d.player.pos);if(!clearPoint(player.pos.x,player.pos.z,player.radius))player.pos.copyFrom(roomCenterWorld(startRoom));player.pos.y=groundAt(player.pos.x,player.pos.z);player.hp=clamp(d.player.hp,1,player.maxhp);player.stam=clamp(d.player.stam??100,0,player.maxstam);player.potCd=Math.max(0,d.player.potCd||0);G.time=d.time||0;G.kills=d.kills||0;G.deadIds=new Set(d.deadIds||[]);for(const e of G.enemies)killNode(e.rig.root);G.enemies=[];G.bossRef=null;G.nextEid=0;for(const a of d.enemies){if(!BESTIARY[a.key]||!Array.isArray(a.pos))continue;const e=makeEntity(a.key,new BABYLON.Vector3(...a.pos),{elite:a.elite,eliteType:a.eliteType});e.eid=a.eid;e.hp=clamp(a.hp,1,e.maxhp);e.yaw=a.yaw||0;e.enraged=a.enraged;if(e.enraged)e.speed*=1.3;if(e.boss)G.bossRef=e;}G.nextEid=Math.max(d.nextEid||0,...G.enemies.map(e=>e.eid+1),1);for(const c of G.crates){const s=d.crates.find(x=>x.cid===c.cid);if(s){c.open=s.open;c.t=c.open?1.4:0;if(c.lid&&c.open)c.lid.rotation.x=1.85;const blocker=world.blockers.find(b=>b.crate===c);c.pos.set(...s.pos);c.pos.y=groundAt(c.pos.x,c.pos.z);c.mesh.position.copyFrom(c.pos);if(blocker){blocker.x=c.pos.x;blocker.z=c.pos.z;}}}for(const d0 of d.drops||[]){const it=reviveItem(d0.item);if(it||d0.isPotion)spawnDrop(it,new BABYLON.Vector3(...d0.pos),d0.isPotion);}G.bossDown=!!d.bossDown;if(G.bossDown)openShaft();indexBlockers();RUN.discovered=new Set(d.run.discovered);RUN.opened=d.run.opened;RUN.floorKills=d.run.floorKills;RUN.questPaid=d.run.questPaid;RUN.currentRoom=null;}
function showModal(title,html,type='menu'){resetInput();document.exitPointerLock?.();G.paused=true;modalType=type;$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modal').classList.add('open');$('modalClose').focus();}
function closeModal(lock=true){$('modal').classList.remove('open');G.paused=false;modalType='';resetInput();if(lock&&G.running)lockPointer();}
function showMenu(){showModal('Expedition paused','<div class="menu-grid"><button id="resumeBtn" class="prim">Return to the vault</button><button id="saveBtn">Save expedition</button><button id="exportBtn">Export save</button><button id="importBtn">Import save</button><button id="settingsBtn">Sound & graphics</button><button id="controlsBtn">Controls</button><button id="journalBtn">Field journal</button><button id="skillsBtn">Skills · spend XP</button><button id="titleBtn">Save & return to title</button></div><p id="saveStatus">Progress saves automatically every 20 seconds during play.</p>');$('resumeBtn').onclick=()=>closeModal();$('saveBtn').onclick=()=>{$('saveStatus').textContent=saveGame()?'Expedition saved.':'Could not save. Use Export save to keep your progress.';};$('exportBtn').onclick=exportSave;$('importBtn').onclick=()=>$('importFile').click();$('settingsBtn').onclick=showSettings;$('controlsBtn').onclick=showControls;$('journalBtn').onclick=showJournal;$('skillsBtn').onclick=showSkills;$('titleBtn').onclick=()=>{if(saveGame()){closeModal(false);G.running=false;document.body.classList.remove('playing');showTitle();}};}
function showSettings(){showModal('Sound & graphics','<div class="setting"><label for="quality">Graphics quality</label><select id="quality"><option value="low">Performance</option><option value="high">High</option><option value="ultra">Ultra</option></select></div><div class="setting"><label for="volume">Sound volume</label><input id="volume" type="range" min="0" max="100" step="1"></div><div class="setting"><label for="sensitivity">Look sensitivity</label><input id="sensitivity" type="range" min="30" max="200" step="5"></div>'+[['shake','Camera impact effects'],['autoLoot','Collect nearby loot automatically'],['meter','Show combat statistics']].map(([id,label])=>'<div class="setting"><label for="'+id+'">'+label+'</label><input id="'+id+'" type="checkbox"></div>').join('')+'<p>Quality changes resolution and particle density immediately. Shadow quality updates on the next floor.</p>','settings');$('quality').value=SETTINGS.quality;$('volume').value=SETTINGS.volume*100;$('sensitivity').value=SETTINGS.sensitivity*100;for(const k of['shake','autoLoot','meter'])$(k).checked=SETTINGS[k];for(const k of['quality','volume','sensitivity','shake','autoLoot','meter'])$(k).oninput=()=>{SETTINGS[k]=k==='quality'?$(k).value:k==='volume'||k==='sensitivity'?Number($(k).value)/100:$(k).checked;applySettings();};}
function applySettings(){try{localStorage.setItem('deepvault.settings.v2',JSON.stringify(SETTINGS));}catch{}document.body.classList.toggle('meter',SETTINGS.meter);if(engine){engine.setHardwareScalingLevel(SETTINGS.quality==='low'?1.6:SETTINGS.quality==='ultra'?1/Math.min(1.5,window.devicePixelRatio||1):1);engine.resize();}if(audioGain)audioGain.gain.value=SETTINGS.volume;if(EXT.particles)EXT.particles.emitRate=SETTINGS.quality==='low'?12:35;}
function showControls(){showModal('Controls','<div class="keys">'+[['Move','W A S D / left stick'],['Look','Mouse / right stick'],['Attack / cast weapon','LMB / RT'],['Block / perfect guard','RMB / LT'],['Dodge','Space / A'],['Runic pulse','F / RB'],['Interact','E / Y'],['Health elixir','Q / X'],['Sprint','Shift / left stick click'],['Inventory','Tab or I / D-pad up'],['Equip best','R / D-pad right'],['Menu / pause','Esc or P / Start']].map(([a,b])=>'<div><span>'+a+'</span><kbd>'+b+'</kbd></div>').join('')+'</div><p>Tap guard just before a frontal hit to stagger nearby attackers. Bows and staves aim toward the reticle with a small targeting assist. On touch screens, use the left pad to move and drag the open right side to look.</p><p>Sable trades rare gear and health potions in the arrival chamber on every floor (gold diamond on the map). Your satchel has unlimited space. Its Sell all unequipped gear button keeps equipped items and every health potion.</p>','controls');}
function showJournal(){const list=[...RUN.journal].filter(k=>BESTIARY[k]);showModal('Field journal','<p>'+list.length+' creatures recorded · '+(RUN.crowns||0)+' crown fragments · '+Math.floor(RUN.elapsed/60)+' minutes explored</p>'+list.map(k=>{const s=BESTIARY[k];return'<div class="journal-card"><b>'+escaped(s.name)+'</b><small>'+(s.passive?'Peaceful wildlife. Flees nearby movement and fighting.':s.boss?'Crowned guardian. Enrages when wounded and summons reinforcements.':s.ai.type==='ranged'?'Ranged hunter. Seeks distance and clear lines of fire.':s.atk.style==='slam'?'Heavy attacker. Dodge out of the warning circle before impact.':s.ai.type==='ambush'?'Ambush predator. Circles, then leaps into striking range.':'Watch its windup. Block frontal blows and counter during recovery.')+'</small></div>';}).join('')+(list.length?'':'<p>Approach wildlife and enemies to record them here.</p>'),'journal');}
function showForge(){if(!nearStation('forge'))return;const w=player.gear.weapon,cost=50+(w?.upgrades||0)*35;showModal('The Wayfarer’s Forge','<p><b>'+player.gold+' gold</b> · '+RUN.shards+' shards</p><div class="journal-card"><b>'+(w?escaped(w.name):'No weapon equipped')+'</b><small>Temper your equipped weapon: +10% base damage. Up to five improvements per weapon.</small></div><div class="menu-grid"><button id="temper">Temper weapon · '+cost+' gold</button><button id="potionBuy">Buy elixir · 30 gold</button><button id="sellCommon">Sell Common & Uncommon satchel gear</button><button id="forgeBest">Equip best gear</button></div><p>Locked items and gear saved in builds are protected. Selling affects spare Common and Uncommon items only. Each sells for 8 + item level × 3 gold.</p>','forge');$('temper').disabled=!w||player.gold<cost||(w.upgrades||0)>=5;$('temper').onclick=()=>{if(!w||player.gold<cost||(w.upgrades||0)>=5)return;player.gold-=cost;w.baseDmg*=1.1;w.upgrades=(w.upgrades||0)+1;w.score=itemScore(w);computeStats(player);spark(player.pos,'#ffd999',12);sound('parry');showForge();};$('potionBuy').disabled=player.gold<30;$('potionBuy').onclick=()=>{if(player.gold<30)return;player.gold-=30;player.potions++;sound('loot');showForge();};$('sellCommon').disabled=!sellableItems().some(i=>i.rarity<2);$('sellCommon').onclick=()=>{sellCommonGear();showForge();};$('forgeBest').onclick=()=>{autoEquip();showForge();};}
function showShrine(){if(!nearStation('shrine'))return;showModal('Shrine of the Wayfarer','<p>Spend relic shards on permanent improvements for this expedition. You hold <b>'+RUN.shards+' shards</b>.</p>'+[['vigor','Vigor','+18 maximum health per rank'],['force','Resolve','+6% weapon damage per rank'],['haste','Stride','+4% movement speed per rank']].map(([k,n,t])=>'<div class="setting"><div>'+n+' · rank '+RUN.perks[k]+'/8<br><small>'+t+'</small></div><button id="perk_'+k+'">'+(2+RUN.perks[k])+' shards</button></div>').join(''),'shrine');for(const k of['vigor','force','haste']){const cost=2+RUN.perks[k];$('perk_'+k).disabled=RUN.shards<cost||RUN.perks[k]>=8;$('perk_'+k).onclick=()=>{if(RUN.shards<cost||RUN.perks[k]>=8)return;RUN.shards-=cost;RUN.perks[k]++;computeStats(player);sound('level');showShrine();};}}
function showVictory(){showModal('The Hollow Crown','<p>You have broken the four guardians and recovered the crown’s scattered fragments. The mountain is quiet—for a moment.</p><p>Your expedition continues beyond the fourth depth, with stronger enemies and equipment that keep scaling.</p><div class="menu-grid"><button class="prim" id="continueCrown">Continue the expedition</button><button id="crownSave">Save this victory</button></div>','victory');$('continueCrown').onclick=()=>closeModal();$('crownSave').onclick=()=>saveGame();}
