function pollGamepad(dt){const p=[...(navigator.getGamepads?.()||[])].find(p=>p&&p.connected);if(!p){if(PAD.active){PAD.active=false;PAD.x=PAD.y=0;mouse.down=mouse.right=0;}return;}const active=p.axes.some(x=>Math.abs(x)>.2)||p.buttons.some(b=>b.pressed);if(active){PAD.active=true;initAudio();}const just=i=>p.buttons[i]?.pressed&&!PAD.last[i];if(just(9)){if(modalType)closeModal(false);else if(G.running)showMenu();}if(modalType||G.invOpen||!G.running){const scope=modalType==='vendor'?$('inv'):modalType?$('modalBox'):G.invOpen?$('inv'):$('veilBox');const opts=[...scope.querySelectorAll('button:not(:disabled),input:not([hidden]),select,.cell,.gear')].filter(e=>e.offsetParent!==null);let i=opts.indexOf(document.activeElement);if(just(12)||just(14)){i=(i-1+opts.length)%opts.length;opts[i]?.focus();}if(just(13)||just(15)){i=(i+1)%opts.length;opts[i]?.focus();}if(just(0)){if(i<0)opts[0]?.focus();else opts[i].click();}if(just(1)){if(G.invOpen)toggleInv(false);else if(modalType)closeModal(false);}PAD.last=p.buttons.map(b=>b.pressed);return;}if(just(12)&&G.running&&!G.paused)toggleInv();if(canAct()){const dead=x=>Math.abs(x)<.16?0:Math.sign(x)*(Math.abs(x)-.16)/.84;PAD.x=PAD.active?dead(p.axes[0]||0):0;PAD.y=PAD.active?dead(p.axes[1]||0):0;mouse.yaw+=dead(p.axes[2]||0)*dt*2.7*SETTINGS.sensitivity;mouse.pitch=clamp(mouse.pitch+dead(p.axes[3]||0)*dt*1.8*SETTINGS.sensitivity,-1.42,.95);if(PAD.active){mouse.down=p.buttons[7]?.pressed?1:0;mouse.right=p.buttons[6]?.pressed?1:0;keys.shift=!!p.buttons[10]?.pressed;}if(just(0))doDodge();if(just(2))drinkPotion();if(just(3))interact();if(just(5))castPulse();if(just(15))autoEquip();}PAD.last=p.buttons.map(b=>b.pressed);}
updateCamera=function(dt){const focus=player.pos.add(new BABYLON.Vector3(0,1.48,0));const cp=Math.cos(mouse.pitch),dir=new BABYLON.Vector3(Math.sin(mouse.yaw)*cp,-Math.sin(mouse.pitch),Math.cos(mouse.yaw)*cp);let dist=4.8;for(let d=.55;d<=4.8;d+=.18){const p=focus.subtract(dir.scale(d));if(solidWorld(p.x,p.y,p.z)){dist=Math.max(.65,d-.25);break;}}const side=new BABYLON.Vector3(Math.cos(mouse.yaw),0,-Math.sin(mouse.yaw));let want=focus.subtract(dir.scale(dist)).add(side.scale(.38));if(solidWorld(want.x,want.y,want.z)||solidWorld(want.x+.12,want.y,want.z)||solidWorld(want.x-.12,want.y,want.z))want=focus.subtract(dir.scale(dist));cam.position=BABYLON.Vector3.Lerp(cam.position,want,1-Math.exp(-dt*15));const kick=SETTINGS.shake?(G.cameraKick||0):0;cam.position.x+=Math.sin(G.time*103)*kick;cam.position.y+=Math.cos(G.time*83)*kick;G.cameraKick=(G.cameraKick||0)*Math.exp(-dt*18);cam.setTarget(focus.add(dir.scale(16)));};
