startLevel=function(depth,carry){return loadLevel(depth,carry);};
descend=function(){if(loadingLevel)return;const carry=playerCarry();carry.hp=player.maxhp;carry.potions=player.potions+2;saveGame(true);return loadLevel(G.depth+1,carry).catch(showLoadError);};
death=function(){if(player.dead)return;player.dead=true;player.rig.anim.death=0;resetInput();sound('death');const generation=scene;setTimeout(()=>{if(scene!==generation||!player.dead)return;const saved=readSave();showModal('The vault remembers','<p>You fell at depth '+G.depth+' after defeating '+G.kills+' enemies. Your last saved expedition is still available.</p><div class="menu-grid">'+(saved?'<button class="prim" id="retrySave">Resume last save</button>':'')+'<button id="retryNew">Begin a new expedition</button></div>','death');if(saved)$('retrySave').onclick=()=>restoreSave(saved);$('retryNew').onclick=()=>{closeModal(false);G.running=false;document.body.classList.remove('playing');showTitle();};},1100);};
let accumulator=0,hudClock=0,ambientClock=0,shadowClock=0;
frame=function(){if(!scene||loadingLevel)return;const raw=Math.min(.1,engine.getDeltaTime()/1000)||.016;pollGamepad(raw);if(canAct()){accumulator=Math.min(.1,accumulator+raw);while(accumulator>=1/60){const dt=1/60;G.time+=dt;RUN.elapsed+=dt;RUN.saveClock+=dt;rebuildBuckets();updatePlayer(dt);for(let i=G.enemies.length-1;i>=0;i--){const e=G.enemies[i];updateEnemy(e,dt);if(e.removed)G.enemies.splice(i,1);}resolveCollisions();player.rig.root.position.copyFrom(player.pos);for(const e of G.enemies)if(!e.dead)e.rig.root.position.copyFrom(e.pos);if(G.bossDown&&!G.shaft)openShaft();if(G.shaft)G.shaft.rotation.y+=dt*.6;adventureTick(dt);updateFX(dt);updateDrops(dt);updateCrates(dt);updateDamageNumbers(dt);accumulator-=dt;}updateCamera(raw);updateLights(raw);updateExploration();hudClock+=raw;if(hudClock>.12){hudClock=0;updateHUD();updateObjectives();drawMinimap();if(SETTINGS.meter)drawMeter(.12);}if(RUN.saveClock>20){RUN.saveClock=0;saveGame(true);}shadowClock+=raw;if(EXT.shadow&&shadowClock>1.2){shadowClock=0;const list=EXT.shadow.getShadowMap()?.renderList;if(list){list.length=0;for(const m of player.rig.root.getChildMeshes())list.push(m);for(const e of G.enemies)if(!e.dead&&BABYLON.Vector3.Distance(e.pos,player.pos)<18)list.push(...e.rig.root.getChildMeshes());for(const merchant of collisionMerchants())if(BABYLON.Vector3.Distance(merchant.pos,player.pos)<18)list.push(...merchant.rig.root.getChildMeshes());for(const m of world.props)if(BABYLON.Vector3.Distance(m.position,player.pos)<18)list.push(m,...m.getChildMeshes());}}}else{accumulator=0;if(player?.dead)updateRig(player,raw);if(!G.running&&player){const focus=player.pos.add(new BABYLON.Vector3(0,1.4,0));const t=performance.now()/12000;const want=focus.add(new BABYLON.Vector3(Math.sin(t)*5,2.2,Math.cos(t)*5));if(!solidWorld(want.x,want.y,want.z))cam.position=BABYLON.Vector3.Lerp(cam.position,want,.02);cam.setTarget(focus);updateLights(raw);}}
 ambientClock+=raw;if(!G.paused&&!G.invOpen&&ambientClock>.075){for(const w of EXT.waters){if(BABYLON.Vector3.Distance(w.mesh.position,player.pos)>22)continue;const p=w.base.slice();for(let i=1;i<p.length;i+=3)p[i]=w.base[i]+Math.sin(p[i-1]*2.6+G.time*1.8+w.phase)*Math.cos(p[i+1]*2.2+G.time)*.02;w.mesh.updateVerticesData(BABYLON.VertexBuffer.PositionKind,p,false,false);}ambientClock=0;}scene.render();};
// Cosmetic construction never advances world-generation randomness.
const refreshInvOriginal=refreshInv;refreshInv=function(){refreshInvOriginal();for(const el of $('inv').querySelectorAll('.cell,.gear')){el.tabIndex=0;el.setAttribute('role','button');el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click();}};}};
const itemProtoOriginal=itemProto;itemProto=function(...args){const seed=SEED;try{return itemProtoOriginal(...args);}finally{SEED=seed;}};
const creatureProtosOriginal=creatureProtos;creatureProtos=function(...args){const seed=SEED;try{return creatureProtosOriginal(...args);}finally{SEED=seed;}};
const propModelOriginal=propModel;propModel=function(...args){const seed=SEED;try{return propModelOriginal(...args);}finally{SEED=seed;}};
const creatureDetailOriginal=creatureDetail;creatureDetail=function(...args){const seed=SEED;try{return creatureDetailOriginal(...args);}finally{SEED=seed;}};
boot=async function(){createUI();showTitle();canvas=$('stage');if(!window.BABYLON){showLoadError(new Error('The graphics engine could not load. Connect to the internet and reload the game.'));return;}try{engine=new BABYLON.Engine(canvas,true,{stencil:true,powerPreference:'high-performance',preserveDrawingBuffer:false},false);bindExpandedInput();applySettings();engine.runRenderLoop(frame);await loadLevel(1,null,17839133,null,false);}catch(err){showLoadError(err);}};
if(document.readyState==='complete')boot();else addEventListener('load',boot);
